"""Verify exact WAV, provenance, overwrite guard and incompatible/incomplete input."""
import base64,json,subprocess,sys,time,traceback
from prepare_vco1_portable import ROOT,sha,write
from render_extended_release import inputs
from joint_cycles_analysis import require
def main():
 names=['tools/check_extended_cli.py','tools/extended_render_cli.py','tools/render_extended_release.py','tools/render_decay_control.py','tools/render_release_voice.py','tools/render_sustained_voice.py','tools/render_conditioned_recipe.py','evidence/voice_extended_listening01.json'];before={n:sha(ROOT/n) for n in names};listening=json.loads((ROOT/names[-1]).read_text(encoding='utf8'));require(listening['passed'],'extended listening admitted');paths=[ROOT/f'references-local/{kind}/524288/selected.txt' for kind in ['sustained-voice01','release-voice01','decay-voice02','extended-release01']];expected=ROOT/next(f['path'] for f in listening['files'] if f['maximum_half_ticks']==524288);private={p.relative_to(ROOT).as_posix():sha(p) for p in [*inputs(*paths),expected]};work=ROOT/'references-local/extended-cli01';require(not work.exists(),'exclusive CLI work');work.mkdir();commands=[];r=dict(passed=False,source_sha256=before,private_used_sha256=private)
 def run(cmd):
  t=time.perf_counter();p=subprocess.run(cmd,cwd=ROOT,capture_output=True,text=True,encoding='utf8',timeout=120,creationflags=subprocess.CREATE_NO_WINDOW);c=dict(command=cmd,exit_code=p.returncode,stdout=p.stdout,stderr=p.stderr,wall_s=time.perf_counter()-t);commands.append(c);return c
 try:
  base=[sys.executable,'-B','tools/extended_render_cli.py']
  for name,p in zip(['held','release','controlled','extended'],paths):base+=['--'+name,str(p)]
  cmd=base+['--output',str(work/'j7.wav')];q=run(cmd);require(q['exit_code']==0 and sha(work/'j7.wav')==sha(expected),'entire extended PCM identity');meta=json.loads((work/'j7.json').read_text(encoding='utf8'));require(meta['input_sha256']=={str(p.resolve()):sha(p) for p in inputs(*paths)} and meta['frames']==3264 and meta['wav_sha256']==sha(expected) and meta['decay_ohm']==1000. and not meta['new_source_event'] and not meta['repeated'],'extended sidecar provenance');saved={n:sha(work/n) for n in ['j7.wav','j7.json']};q=run(cmd);require(q['exit_code']!=0 and 'preserve existing WAV and sidecar' in q['stderr'] and saved=={n:sha(work/n) for n in saved},'existing outputs unchanged')
  with paths[-1].open(encoding='utf8') as f:lines=[f.readline().rstrip('\n'),f.readline().rstrip('\n')]
  for n in ['incoming-original.ckp','final.ckp']:(work/n).write_bytes(paths[-1].with_name(n).read_bytes())
  fields=lines[1].split(',');require(len(fields)==459,'extended seam fixture');fields[195]=format(float(fields[195])+1e-3,'.17e');fixture=work/'mismatched-seam.txt';fixture.write_text(lines[0]+'\n'+','.join(fields)+'\n',encoding='utf8',newline='\n');bad=base[:-1]+[str(fixture),'--output',str(work/'rejected.wav')];q=run(bad);require(q['exit_code']!=0 and 'full extended seam state' in q['stderr'] and not (work/'rejected.wav').exists() and not (work/'rejected.json').exists(),'reject incompatible seam before publication')
  fixture=work/'incomplete.txt';fixture.write_text('\n'.join(lines)+f'\nBOUNDARY,0,23300407296,0.00000000000000000e0,0\n',encoding='utf8',newline='\n');q=run(base[:-1]+[str(fixture),'--output',str(work/'incomplete.wav')]);require(q['exit_code']!=0 and 'complete extended observations' in q['stderr'] and not (work/'incomplete.wav').exists() and not (work/'incomplete.json').exists(),'reject incomplete trajectory before publication');r.update(passed=True,user_cli_wav_identical=True,sidecar_verified=True,existing_output_rejected_without_mutation=True,mismatched_seam_rejected_before_publication=True,incomplete_trace_rejected_before_publication=True,integration_checks=4)
 except Exception:
  r['failure']=traceback.format_exc();r['failed_source_base64']={n:base64.b64encode((ROOT/n).read_bytes()).decode() for n in names if n.endswith('.py')}
  try:run(base+['--output',str(work/'failure-replay.wav')])
  except Exception:r['replay']=traceback.format_exc()
 r.update(commands=commands,source_sha256_after={n:sha(ROOT/n) for n in names},private_used_sha256_after={n:sha(ROOT/n) for n in private},outputs=[dict(path=p.relative_to(ROOT).as_posix(),sha256=sha(p),bytes=p.stat().st_size) for p in sorted(work.iterdir()) if p.is_file()]);require(before==r['source_sha256_after'] and private==r['private_used_sha256_after'],'stable extended CLI inputs');write('evidence/voice_extended_cli01.json',r);print('EXTENDED_CLI',r['passed'],r.get('failure',''));require(r['passed'],'extended CLI')
if __name__=='__main__':main()
